            Add(translations,  ModTextKey.PropertyMenuCommercialGarageTitle,  "Commercial Garage",  "Garage commercial",  "Garage commerciale",  "Garaje comercial",  "Коммерческий гараж",  "Garagem comercial",  "Ticari garaj");
            Add(translations,  ModTextKey.PropertyMenuCommercialGarageSubtitle,  "Retrieve, store, and swap vehicles",  "Récupérez, stockez et échangez des véhicules",  "Recupera, deposita e scambia veicoli",  "Recoge, guarda e intercambia vehículos",  "Получайте, храните и меняйте транспорт",  "Retire, guarde e troque veículos",  "Araçları alın, depolayın ve değiştirin");
            Add(translations,  ModTextKey.PropertyMenuVehicleTitle,  "Vehicle",  "Véhicule",  "Veicolo",  "Vehículo",  "Транспорт",  "Veículo",  "Araç");
            Add(translations,  ModTextKey.PropertyMenuVehicleSubtitle,  "Retrieve, store, reserve, or close the contract",  "Récupérez, stockez, mettez en réserve ou clôturez le contrat",  "Recupera, deposita, metti in riserva o chiudi il contratto",  "Recoge, guarda, reserva o cierra el contrato",  "Получайте, храните, отправляйте в резерв или закрывайте контракт",  "Retire, guarde, reserve ou encerre o contrato",  "Aracı alın, depolayın, yedeğe alın veya sözleşmeyi kapatın");
